// Rebuilds the generated files behind the app pictures (website/app/):
//
//   app/app.css    the app's own stylesheets, copied unchanged and joined in
//                  the order the app loads them, so the hero is drawn by the
//                  same rules as the real window and cannot drift from it.
//   app/phone.css  the same for the companion app (mobile/src).
//   app/orb.js     the orb animation the app uses (the thinking-orbs package,
//                  MIT), bundled for a plain page.
//
// Run from the repo root after the app's styles change:  node website/sync-app.mjs

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "src");

// The sheets the shown window needs, in the order the running app loads them
// (the order of its <style> tags in a dev build).
const SHEETS = [
  "styles/tokens.css",
  "styles/global.css",
  "styles/menu.css",
  "components/Mark/Mark.css",
  "components/TopBar/TabStrip.css",
  "components/TopBar/TopBar.css",
  "components/EngineStatus/EngineStatus.css",
  "components/Ticker/Ticker.css",
  "components/Personas/PersonaGlyph.css",
  "components/Waiting/Waiting.css",
  "components/Rail/Rail.css",
  "components/Workbench/Workbench.css",
  "components/Conversation/Conversation.css",
  "components/Memory/Memory.css",
  "components/Context/Context.css",
  "components/ModelPicker/ModelPicker.css",
  "components/Composer/EffortPicker.css",
  "components/Composer/ContextMeter.css",
  "components/Composer/ModelControl.css",
  "components/Composer/CommandMenu.css",
  "components/Composer/ModifierChips.css",
  "components/Composer/MemberRow.css",
  "components/Composer/ModeChips.css",
  "components/Composer/RunBar.css",
  "components/Composer/SuggestionChip.css",
  "components/Voice/MicButton.css",
  "components/Composer/Composer.css",
  "routes/Chat.css",
  "App.css",
];

const css = SHEETS.map((f) => `/* ---- ${f} ---- */\n${readFileSync(join(src, f), "utf8")}`).join("\n\n");
writeFileSync(
  join(here, "app", "app.css"),
  `/* GENERATED by website/sync-app.mjs from the app's own stylesheets. Do not edit. */\n\n${css}\n`
);

// The phone screens (app/phone.html) are drawn by the companion app's own sheets.
const PHONE_SHEETS = ["styles/tokens.css", "styles/app.css", "components/Mark.css"];
const phoneSrc = join(here, "..", "mobile", "src");
const phoneCss = PHONE_SHEETS.map((f) => `/* ---- mobile/src/${f} ---- */\n${readFileSync(join(phoneSrc, f), "utf8")}`).join("\n\n");
writeFileSync(
  join(here, "app", "phone.css"),
  `/* GENERATED by website/sync-app.mjs from the phone app's own stylesheets. Do not edit. */\n\n${phoneCss}\n`
);

await build({
  entryPoints: [join(here, "app", "orb-entry.js")],
  outfile: join(here, "app", "orb.js"),
  bundle: true,
  minify: true,
  format: "iife",
  target: "es2020",
  banner: { js: "/* thinking-orbs (MIT), bundled by website/sync-app.mjs */" },
});

console.log("website/app/app.css, website/app/phone.css and website/app/orb.js written");
